// 変更ファイルに OWNER_APPROVAL_QUEUE.md が含まれるか確認
const payload = $input.first().json;
const commits = payload.commits || [];
const targetFile = 'ai-agent/queue/OWNER_APPROVAL_QUEUE.md';

const hasQueueUpdate = commits.some(commit => {
  const modified = commit.modified || [];
  const added = commit.added || [];
  return [...modified, ...added].includes(targetFile);
});

if (!hasQueueUpdate) {
  // OWNER_APPROVAL_QUEUE.md の変更でなければスキップ
  return [{ json: { skip: true } }];
}

const latestCommit = commits[commits.length - 1];
return [{ json: {
  skip: false,
  pusher: payload.pusher?.name || 'AI Sales Agent',
  commitMessage: latestCommit?.message || '',
  timestamp: new Date().toISOString()
}}];

// Base64 デコードして最新の AQ エントリを抽出
const content = Buffer.from($input.first().json.content, 'base64').toString('utf-8');

// 最新の [AQ-YYYYMMDD-NNN] エントリを抽出
const aqPattern = /## \[(AQ-\d{8}-\d{3})\] (.+?) — 承認待ち/g;
const matches = [...content.matchAll(aqPattern)];

if (matches.length === 0) {
  return [{ json: { found: false } }];
}

// 最後のエントリを取得
const lastMatch = matches[matches.length - 1];
const entryId = lastMatch[1];
const companyName = lastMatch[2];

// Confidence Score の抽出
const scoreMatch = content.match(new RegExp(`${entryId}[\\s\\S]+?Confidence Score.*?(\\d+)%`));
const score = scoreMatch ? scoreMatch[1] : '—';

// 承認期限の抽出
const deadlineMatch = content.match(new RegExp(`${entryId}[\\s\\S]+?承認期限.*?(\\d{4}-\\d{2}-\\d{2})`));
const deadline = deadlineMatch ? deadlineMatch[1] : '—';

return [{ json: {
  found: true,
  entryId,
  companyName,
  confidenceScore: score,
  approvalDeadline: deadline,
  queueUrl: 'https://github.com/PHOSARA01/phosara/blob/main/ai-agent/queue/OWNER_APPROVAL_QUEUE.md'
}}];
